using System.Text.RegularExpressions;
using SupportDesk.Application.Notifications;

namespace SupportDesk.UnitTests.Notifications;

/// <summary>
/// Deep links generated by the server (notifications, digests, push payloads, search hits, AI references) must open a real
/// desk route. The route list mirrors clients/projects/desk/src/app/app.routes.ts and the feature *.routes.ts files —
/// update it when routes change. Links are checked on their path (query strings such as <c>?c=</c> are ignored).
/// </summary>
public sealed partial class DeskLinkTests
{
    /// <summary>Desk routes (":x" = one path parameter).</summary>
    public static readonly string[] DeskRoutes =
    [
        "/login", "/accept-invite", "/command", "/approvals", "/notifications", "/me", "/forbidden", "/subscription", "/engineering",
        "/tickets", "/tickets/new", "/tickets/:id",
        "/inbox", "/inbox/chat",
        "/customers", "/customers/contacts", "/customers/contacts/:id", "/customers/duplicates", "/customers/activities", "/customers/groups",
        "/customers/:id",
        "/products", "/products/families", "/products/installations", "/products/licences", "/products/assets", "/products/install-base",
        "/products/contracts", "/products/contracts/:id", "/products/renewals", "/products/erp",
        "/teams", "/teams/departments", "/teams/teams", "/teams/agents", "/teams/agents/:id", "/teams/skills", "/teams/shifts", "/teams/delegations",
        "/teams/monitor",
        "/sla", "/sla/policies", "/sla/policies/new", "/sla/policies/:id", "/sla/calendars", "/sla/breaches",
        "/automation", "/automation/rules", "/automation/rules/new", "/automation/rules/:id", "/automation/executions", "/automation/blueprints",
        "/automation/blueprints/new", "/automation/blueprints/:id", "/automation/tickets/:ref",
        "/kb", "/kb/articles", "/kb/articles/new", "/kb/articles/:id", "/kb/categories", "/kb/feedback", "/kb/community", "/kb/community/:id",
        "/kb/flows", "/kb/flows/new", "/kb/flows/:id", "/kb/analytics",
        "/analytics", "/analytics/dashboards", "/analytics/dashboards/:id", "/analytics/reports", "/analytics/reports/:key", "/analytics/schedules",
        "/analytics/exports",
        "/ai", "/ai/ask", "/ai/search", "/ai/proposals", "/ai/anomalies", "/ai/tickets/:id",
        "/admin", "/admin/channels", "/admin/webhooks", "/admin/ai", "/admin/engineering", "/admin/collaboration",
    ];

    /// <summary>Links that intentionally target another app: the customer portal (served under /portal) and the mobile customer app.</summary>
    private static readonly string[] OtherApps = ["/portal", "/customer/tickets/"];

    /// <summary>Server paths that are not navigation links (API URLs, hubs, JSON-patch paths of tracker adapters).</summary>
    private static readonly string[] NotLinks = ["/api/", "/hubs/", "/fields/", "/relations/"];

    public static bool IsDeskRoute(string link)
    {
        var path = link.Split('?', '#')[0];
        if (path.Length > 1) path = path.TrimEnd('/');
        var segments = path.Split('/', StringSplitOptions.RemoveEmptyEntries);
        return DeskRoutes.Any(route =>
        {
            var parts = route.Split('/', StringSplitOptions.RemoveEmptyEntries);
            return parts.Length == segments.Length && parts.Zip(segments).All(p => p.First.StartsWith(':') || p.First == p.Second);
        });
    }

    [Fact]
    public void Generated_desk_links_open_known_routes()
    {
        var id = Guid.NewGuid();
        string[] links =
        [
            DeskLinks.Ticket(id), DeskLinks.TicketQueue("deleted"), DeskLinks.Chat(id), DeskLinks.Conversation(id), DeskLinks.Customer(id),
            DeskLinks.Contact(id), DeskLinks.Contract(id), DeskLinks.KbArticle(id), DeskLinks.CommunityTopic(id), DeskLinks.Approvals,
            DeskLinks.Notifications, DeskLinks.AiAnomalies, DeskLinks.AiProposals, DeskLinks.AdminAi, DeskLinks.AdminWebhooks
        ];
        Assert.All(links, link => Assert.True(IsDeskRoute(link), $"'{link}' is not a desk route"));
    }

    [Fact]
    public void Chat_links_open_the_chat_console_with_the_conversation_selected()
    {
        var id = Guid.NewGuid();
        Assert.Equal($"/inbox/chat?c={id}", DeskLinks.Chat(id));
        Assert.False(IsDeskRoute($"/conversations/{id}"));
        Assert.False(IsDeskRoute("/analytics/anomalies"));
    }

    /// <summary>
    /// Every desk-style link literal in the application layer ("/x…" or $"/x/{…}") must match a desk route — this catches
    /// links built by hand in any module (notifications, search hits, AI references, ERP responses…).
    /// </summary>
    [Fact]
    public void Every_link_literal_in_the_application_layer_opens_a_known_route()
    {
        var root = RepositoryRoot();
        var files = Directory.EnumerateFiles(Path.Combine(root, "src", "SupportDesk.Application"), "*.cs", SearchOption.AllDirectories)
            .Where(f => !f.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}") && !f.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}"))
            .ToList();
        Assert.NotEmpty(files);
        var failures = new List<string>();
        var checkedLinks = 0;
        foreach (var file in files)
        {
            var lines = File.ReadAllLines(file);
            for (var i = 0; i < lines.Length; i++)
                foreach (Match m in LinkLiteral().Matches(lines[i]))
                {
                    var literal = Regex.Replace(m.Groups["path"].Value, @"\{[^}]*\}", "x");
                    if (NotLinks.Any(p => literal.StartsWith(p, StringComparison.Ordinal)) || OtherApps.Any(p => literal.StartsWith(p, StringComparison.Ordinal))) continue;
                    checkedLinks++;
                    if (!IsDeskRoute(literal)) failures.Add($"{Path.GetRelativePath(root, file)}:{i + 1}: {m.Value}");
                }
        }
        Assert.True(checkedLinks > 10, $"Only {checkedLinks} link literals found — is the scan still looking at the right folder?");
        Assert.True(failures.Count == 0, "Links that do not match a desk route:\n" + string.Join("\n", failures));
    }

    /// <summary>A string literal (optionally interpolated) that starts with "/" and a lower-case letter — not an escaped quote and not the tail of a concatenation.</summary>
    [GeneratedRegex("""(?<![\\\w])(?<!\+\s*)\$?"(?<path>/[a-z][^"\s]*)""")]
    private static partial Regex LinkLiteral();

    private static string RepositoryRoot()
    {
        for (var dir = new DirectoryInfo(AppContext.BaseDirectory); dir is not null; dir = dir.Parent)
            if (File.Exists(Path.Combine(dir.FullName, "SupportDesk.slnx"))) return dir.FullName;
        throw new InvalidOperationException("SupportDesk.slnx not found above the test output folder.");
    }
}
